22	import org.springframework.web.server.ResponseStatusException;
23	import org.springframework.web.servlet.HandlerInterceptor;
24	import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
25	import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
26	
27	/** While a user's screen shows a sheet as of a date, every request it makes carries that date in
28	 *  {@link #HEADER}: each read answers with the sheet as it stood at the end of that date, and every
29	 *  changing request is refused (403, the date echoed in {@link #HEADER}) before it reaches its
30	 *  handler, so it writes nothing; a handler
31	 *  marked {@link AsOfAllowed} changes nothing and is let through. */
32	@Configuration
33	public class AsOfGuard implements HandlerInterceptor, WebMvcConfigurer {
34	
35	    /** The header carrying the date (yyyy-mm-dd) the screen shows the sheet as of. */
36	    public static final String HEADER = "X-As-Of";
37	
38	    private static final Set<String> READING = Set.of("GET", "HEAD", "OPTIONS");
39	
40	    @Override
41	    public void addInterceptors(InterceptorRegistry registry) {
42	        registry.addInterceptor(this).addPathPatterns("/api/sheets/**");
43	    }
44	
45	    @Override
46	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
47	        String asOf = request.getHeader(HEADER);
48	        if (asOf == null || asOf.isBlank() || READING.contains(request.getMethod())
49	                || !(handler instanceof HandlerMethod method) || method.hasMethodAnnotation(AsOfAllowed.class)) {
50	            return true;
51	        }
52	        response.setHeader(HEADER, asOf.trim());
53	        throw new ResponseStatusException(HttpStatus.FORBIDDEN,
54	                "The sheet is shown as of " + asOf.trim() + ": clear the as-of date to change anything");
55	    }
56	}
