199	     *  by id in list order, its claims by id, its rates, its periods by id, its statements by id (oldest first), its
200	     *  patrons and watches, its roles (by user name), its delegations by id and its permission
201	     *  matrix; none of it is stored. */
202	    public record AsOf(Sheet sheet, Map<Long, Person> people, List<Rate> rates, Map<Long, Claim> claims,
203	            Map<Long, Period> periods, Map<Long, PersonStatement> statements, List<PersonPatron> patrons,
204	            List<PersonWatch> watches, List<SheetRole> roles, Map<Long, SheetDelegation> delegations,
205	            Map<Permission, String> permissions) {
206	    }
207	
208	    private final JdbcTemplate jdbc;
209	    private final JsonMapper json;
210	
211	    public HistoryService(JdbcTemplate jdbc, JsonMapper json) {
212	        this.jdbc = jdbc;
213	        this.json = json;
214	    }
215	
216	    /** Write the version of the sheet's settings now, if it differs from the last one. */
217	    public void recordSheet(Sheet sheet) {
218	        List<SettingState> settings = sheet.getDatedSettings().values().stream()
219	                .flatMap(List::stream)
220	                .map(d -> new SettingState(d.getKey(), d.getFrom(), d.getValue()))
221	                .toList();
222	        write(sheet.getId(), SHEET, sheet.getId(), new SheetState(sheet.getPolicyDate(), settings,
223	                sheet.getPeriodNumberingFrom(), sheet.getGraceDays(), sheet.isArchived(), sheet.getEntryDate(),
224	                sheet.getPot(), sheet.getFiscalStartMonth(), sheet.getAlertThreshold(), sheet.getEscalateAfter(),
225	                sheet.getReviewSla(), sheet.getProofKinds()));
226	    }
227	
228	    /** Write the version of an entity of the sheet now, if it differs from the last one. */
229	    void record(Object entity) {
230	        if (entity instanceof Claim c) {
231	            write(c.getSheetId(), CLAIM, String.valueOf(c.getId()), new ClaimState(c.getPersonId(), c.getAmount(),
232	                    c.getDate(), c.getDueBy(), c.getStatus(), c.getNumber(), c.getSettledDue(), c.isStated(),
233	                    c.getStatedDue(), c.getCorrects(), c.getDeferredUntil(), c.getNote(), c.getOpenedBy(),
234	                    c.getListed(), c.getProofs(), c.getSplitFrom(), c.isLateEntry(), c.getReminded(),
235	                    c.getRef(), c.getTags(), c.getVoidReason(), c.getEditedBy(), c.getBatch(), c.getAdded(),
236	                    c.isEscalated(), c.getReviewOn(), c.isWaived(), c.getPhotoProofs(), c.isHeld()));
237	        } else if (entity instanceof Person p) {
238	            List<Person.DatedGrade> all = p.getGrades();
239	            write(p.getSheetId(), PERSON, String.valueOf(p.getId()), new PersonState(p.getName(), all.get(0).grade(),
240	                    all.stream().skip(1).map(g -> new GradeState(g.from(), g.grade())).toList(), p.getTerms(),
241	                    p.getRetiredFrom(), p.getHolds().stream().map(h -> new HoldState(h.from(), h.to())).toList(),
242	                    p.getContact(), p.getAliases(), p.getPosition(), p.getOriginSheetId(),
243	                    p.getRetirements().stream().map(r -> new HoldState(r.from(), r.to())).toList(), p.getTags(),
244	                    p.getDatedTerms().stream().map(t -> new TermsState(t.from(), t.terms())).toList(),
245	                    p.getFlagReason(), p.getFlagUntil()));
246	        } else if (entity instanceof Rate r) {
247	            write(r.getSheetId(), RATE, String.valueOf(r.getId()),
248	                    new RateState(r.getGrade(), r.getPct(), r.getFrom(), r.getTo(), r.getVersion(),
249	                            r.getAfterClaim(), r.getEarlier()));
250	        } else if (entity instanceof Sheet s) {
251	            recordSheet(s);
252	        } else if (entity instanceof Period p) {
253	            write(p.getSheetId(), PERIOD, String.valueOf(p.getId()), new PeriodState(p.getName(), p.getFrom(), p.getTo(),
254	                    p.isClosed(), p.isSoftClosed(), new TreeMap<>(p.getClosedPersonTotals()), p.getCap(),
255	                    p.isCarriedFixed() ? new TreeMap<>(p.getClosedPersonCarried()) : null, new TreeMap<>(p.getOpenings()), p.isLocked()));
256	        } else if (entity instanceof PersonStatement st) {
257	            write(st.getSheetId(), STATEMENT, String.valueOf(st.getId()), new StatementState(st.getPersonId(),
258	                    st.getDueTotal(), st.getClaims(), st.getTakenOn(), st.getAsOf(), st.getTakenBy()));
259	        } else if (entity instanceof PersonPatron pp) {
260	            write(pp.getSheetId(), PATRON, String.valueOf(pp.getId()), new PatronState(pp.getPersonId(), pp.getPatronId()));
261	        } else if (entity instanceof PersonWatch w) {
262	            write(w.getSheetId(), WATCH, String.valueOf(w.getId()), new WatchState(w.getPersonId(), w.getUserName()));
263	        } else if (entity instanceof SheetRole r) {
264	            write(r.getSheetId(), ROLE, r.getUser(), new RoleState(r.getUser(), r.getRole().key()));
265	        } else if (entity instanceof SheetDelegation d) {
266	            write(d.getSheetId(), DELEGATION, String.valueOf(d.getId()),
267	                    new DelegationState(d.getUser(), d.getSteward(), d.getFrom(), d.getTo()));
268	        } else if (entity instanceof SheetPermission sp) {
269	            write(sp.getSheetId(), PERMISSION, sp.getAction().key(), sp.getRoles());
270	        }
271	    }
272	
273	    /** Write that an entity of the sheet is gone now: a person merged or transferred away (with
274	     *  their claims), a statement cancelled, a watch stopped, a permission set back to its standing rule. */
275	    void removed(Object entity) {
276	        if (entity instanceof Person p) {
277	            writeText(p.getSheetId(), PERSON, String.valueOf(p.getId()), REMOVED);
278	        } else if (entity instanceof Claim c) {
279	            writeText(c.getSheetId(), CLAIM, String.valueOf(c.getId()), REMOVED);
280	        } else if (entity instanceof PersonStatement st) {
281	            writeText(st.getSheetId(), STATEMENT, String.valueOf(st.getId()), REMOVED);
282	        } else if (entity instanceof PersonPatron pp) {
283	            writeText(pp.getSheetId(), PATRON, String.valueOf(pp.getId()), REMOVED);
284	        } else if (entity instanceof PersonWatch w) {
285	            writeText(w.getSheetId(), WATCH, String.valueOf(w.getId()), REMOVED);
286	        } else if (entity instanceof SheetDelegation d) {
287	            writeText(d.getSheetId(), DELEGATION, String.valueOf(d.getId()), REMOVED);
288	        } else if (entity instanceof SheetRole r) {
289	            writeText(r.getSheetId(), ROLE, r.getUser(), REMOVED);
290	        } else if (entity instanceof SheetPermission sp) {
291	            writeText(sp.getSheetId(), PERMISSION, sp.getAction().key(), REMOVED);
292	        }
293	    }
294	
295	    private void write(String sheetId, String kind, String entityId, Object state) {
296	        writeText(sheetId, kind, entityId, json.writeValueAsString(state));
297	    }
298	
299	    private void writeText(String sheetId, String kind, String entityId, String text) {
300	        List<String> last = jdbc.queryForList(
301	                "SELECT state FROM history WHERE sheet_id = ? AND kind = ? AND entity_id = ? ORDER BY id DESC LIMIT 1",
302	                String.class, sheetId, kind, entityId);
303	        if (!last.isEmpty() && last.get(0).equals(text)) {
304	            return;
305	        }
306	        List<Date> today = jdbc.queryForList("SELECT today FROM sheet WHERE id = ?", Date.class, sheetId);
307	        LocalDate madeOn = today.isEmpty() ? LocalDate.now() : today.get(0).toLocalDate();
308	        jdbc.update("INSERT INTO history (sheet_id, kind, entity_id, made_on, state) VALUES (?, ?, ?, ?, ?)",
309	                sheetId, kind, entityId, Date.valueOf(madeOn), text);
310	    }
311	
312	    /** The sheet as it stood at the end of {@code on}: each of its entities and its settings in the
313	     *  last version a change made while the sheet's today was on or before it left (one with none,
314	     *  or removed then, was not there), and {@code on} as its today. */
315	    public AsOf asOf(String sheetId, LocalDate on) {
316	        Map<String, String> latest = new LinkedHashMap<>();
317	        jdbc.query("SELECT kind, entity_id, made_on, state FROM history WHERE sheet_id = ? ORDER BY id",
318	                rs -> {
319	                    if (!rs.getDate("made_on").toLocalDate().isAfter(on)) {
320	                        latest.put(rs.getString("kind") + "/" + rs.getString("entity_id"), rs.getString("state"));
321	                    }
322	                }, sheetId);
323	        Sheet sheet = new Sheet(sheetId, "", on);
324	        Map<Long, Person> people = new TreeMap<>();
325	        List<Rate> rates = new ArrayList<>();
326	        Map<Long, Claim> claims = new LinkedHashMap<>();
327	        Map<Long, Period> periods = new TreeMap<>();
328	        Map<Long, PersonStatement> statements = new TreeMap<>();
329	        List<PersonPatron> patrons = new ArrayList<>();
330	        List<PersonWatch> watches = new ArrayList<>();
331	        List<SheetRole> roles = new ArrayList<>();
332	        Map<Long, SheetDelegation> delegations = new TreeMap<>();
333	        Map<Permission, String> permissions = new EnumMap<>(Permission.class);
334	        latest.forEach((key, state) -> {
335	            if (state.equals(REMOVED)) {
336	                return;
337	            }
338	            String kind = key.substring(0, key.indexOf('/'));
339	            String id = key.substring(key.indexOf('/') + 1);
340	            switch (kind) {
341	                case SHEET -> {
342	                    SheetState s = json.readValue(state, SheetState.class);
343	                    sheet.setPolicyDate(s.policyDate());
344	                    s.settings().forEach(d -> sheet.recordSetting(d.key(), d.from(), d.value()));
345	                    sheet.setPeriodNumberingFrom(s.periodNumberingFrom());
346	                    sheet.setGraceDays(s.graceDays());
347	                    sheet.setEscalateAfter(s.escalateAfter());
348	                    sheet.setReviewSla(s.reviewSla());
349	                    sheet.setEntryDate(s.entryDate());
350	                    sheet.setPot(s.pot());
351	                    sheet.setAlertThreshold(s.alertThreshold());
352	                    sheet.setProofKinds(s.proofKinds());
353	                    sheet.setFiscalStartMonth(s.fiscalStartMonth() == null ? 1 : s.fiscalStartMonth());
354	                    if (s.archived()) {
355	                        sheet.archive();
356	                    }
357	                }
358	                case PERSON -> people.put(Long.valueOf(id), personOf(sheetId, Long.parseLong(id), json.readValue(state, PersonState.class)));
359	                case RATE -> {
360	                    RateState r = json.readValue(state, RateState.class);
361	                    rates.add(new Rate(sheetId, r.grade(), r.from(), r.to(), r.pct(), r.version() == null ? 1 : r.version(),
362	                            r.afterClaim(), r.earlier() == null ? List.of() : r.earlier()));
363	                }
364	                case CLAIM -> claims.put(Long.valueOf(id), claimOf(sheetId, Long.parseLong(id), json.readValue(state, ClaimState.class)));
365	                case PERIOD -> {
366	                    PeriodState p = json.readValue(state, PeriodState.class);
367	                    Period period = new Period(sheetId, p.name(), p.from(), p.to());
368	                    period.setCap(p.cap());
369	                    period.setLocked(Boolean.TRUE.equals(p.locked()));
370	                    if (p.openings() != null) {
371	                        p.openings().forEach(period::addOpening);
372	                    }
373	                    if (p.closed()) {
374	                        period.close(p.personTotals(), p.personCarried());
375	                    } else if (p.softClosed()) {
376	                        period.softClose(p.personTotals(), p.personCarried());
377	                    }
378	                    periods.put(Long.valueOf(id), period);
379	                }
380	                case STATEMENT -> {
381	                    StatementState st = json.readValue(state, StatementState.class);
382	                    statements.put(Long.valueOf(id), new PersonStatement(sheetId, st.personId(), st.dueTotal(),
383	                            st.claims(), st.takenOn(), st.asOf(), st.takenBy()));
384	                }
385	                case PATRON -> {
386	                    PatronState pp = json.readValue(state, PatronState.class);
387	                    patrons.add(new PersonPatron(sheetId, pp.personId(), pp.patronId()));
388	                }
389	                case WATCH -> {
390	                    WatchState w = json.readValue(state, WatchState.class);
391	                    watches.add(new PersonWatch(sheetId, w.personId(), w.user()));
392	                }
393	                case ROLE -> {
394	                    RoleState r = json.readValue(state, RoleState.class);
395	                    roles.add(new SheetRole(sheetId, r.user(), Role.of(r.role())));
396	                }
397	                case DELEGATION -> {
398	                    DelegationState d = json.readValue(state, DelegationState.class);
399	                    delegations.put(Long.valueOf(id), new SheetDelegation(sheetId, d.user(), d.steward(), d.from(), d.to()));
400	                }
401	                case PERMISSION -> permissions.put(Permission.of(id), json.readValue(state, String.class));
402	                default -> {
403	                }
404	            }
405	        });
406	        rates.sort(Comparator.comparing(Rate::getGrade));
407	        roles.sort(Comparator.comparing(SheetRole::getUser));
408	        Map<Long, Claim> claimsListed = new LinkedHashMap<>();
409	        claims.entrySet().stream()
410	                .sorted(Comparator.comparing((Map.Entry<Long, Claim> e) -> e.getValue().getListed()).reversed())
411	                .forEach(e -> claimsListed.put(e.getKey(), e.getValue()));
412	        Map<Long, Person> peopleListed = new LinkedHashMap<>();
413	        people.entrySet().stream()
414	                .sorted(Comparator.comparingLong((Map.Entry<Long, Person> e) -> e.getValue().getPosition())
415	                        .thenComparing(Map.Entry::getKey))
416	                .forEach(e -> peopleListed.put(e.getKey(), e.getValue()));
417	        return new AsOf(sheet, peopleListed, rates, claimsListed, periods, statements, patrons, watches, roles,
418	                delegations, permissions);
419	    }
420	
421	    private static Person personOf(String sheetId, long id, PersonState s) {
422	        Person p = new Person(sheetId, s.name(), s.grade());
423	        s.grades().forEach(g -> p.recordGrade(g.grade(), g.from()));
424	        p.setTerms(s.terms());
425	        if (s.datedTerms() != null) { // a version written before terms were dated has none
426	            s.datedTerms().forEach(t -> p.recordTerms(t.terms(), t.from()));
427	        }
428	        p.setContact(s.contact());
429	        p.setTags(s.tags());
430	        p.setRetiredFrom(s.retiredFrom());
431	        s.holds().forEach(h -> p.addHold(h.from(), h.to()));
432	        // a version written before people had positions is placed by its id, as they then were
433	        p.setPosition(s.position() != null ? s.position() : id);
434	        if (s.aliases() != null) { // a version written before people had aliases has none
435	            s.aliases().forEach(p::addAlias);
436	        }
437	        p.setOriginSheetId(s.originSheetId());
438	        if (s.retirements() != null) { // a version written before people could be unretired has none
439	            s.retirements().forEach(r -> p.addRetirement(r.from(), r.to()));
440	        }
441	        p.flag(s.flagReason(), s.flagUntil()); // a version written before people were flagged has none
442	        return p;
443	    }
444	
445	    private static Claim claimOf(String sheetId, long id, ClaimState s) {
446	        Claim c = new Claim(sheetId, s.personId(), s.amount(), s.date(), s.dueBy(), "");
447	        // a version written before claims kept what they were added as was added as its own id
448	        c.setAdded(s.added() != null ? s.added() : id);
449	        c.setStatus(s.status());
450	        c.setNumber(s.number());
451	        c.setSettledDue(s.settledDue());
452	        c.setCorrects(s.corrects());
453	        c.setDeferredUntil(s.deferredUntil());
454	        c.setNote(s.note() == null ? "" : s.note());
455	        c.setOpenedBy(s.openedBy());
456	        c.setListed(s.listed());
457	        c.setProofs(s.proofs());
458	        c.setPhotoProofs(s.photoProofs() == null ? 0 : s.photoProofs());
459	        c.setSplitFrom(s.splitFrom());
460	        c.setLateEntry(s.lateEntry());
461	        c.setReminded(s.reminded());
462	        c.setEscalated(Boolean.TRUE.equals(s.escalated()));
463	        c.setWaived(Boolean.TRUE.equals(s.waived()));
464	        c.setHeld(Boolean.TRUE.equals(s.held()));
465	        c.setReviewOn(s.reviewOn());
466	        c.setRef(s.ref());
467	        c.setTags(s.tags());
468	        c.setVoidReason(s.voidReason());
469	        c.setEditedBy(s.editedBy());
470	        c.setBatch(s.batch());
471	        if (s.stated()) {
472	            c.bind(s.statedDue());
473	        }
474	        return c;
475	    }
476	}
477	import { HttpInterceptorFn } from '@angular/common/http';
478	import { inject } from '@angular/core';
479	import { Session } from './session';
480	
481	/** While the screen shows the sheet as of a date, every sheet request carries it: the server then
482	 *  answers each read with the sheet as it stood at the end of that date and refuses every change. */
483	export const asOfInterceptor: HttpInterceptorFn = (req, next) => {
484	  const asOf = inject(Session).asOf();
485	  return asOf !== null && req.url.startsWith('/api/sheets/')
486	    ? next(req.clone({ setHeaders: { 'X-As-Of': asOf } }))
487	    : next(req);
488	};
489	-- Each version of a sheet's claims, people, rates and dated settings, as a change left it, with the
490	-- sheet's today when the change was made: a statement taken as of a date rebuilds the sheet from the
491	-- last version of each made while the sheet's today was on or before that date.
492	CREATE TABLE history (
493	    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
494	    sheet_id   VARCHAR(100)   NOT NULL,
495	    kind       VARCHAR(20)    NOT NULL,
496	    entity_id  VARCHAR(100)   NOT NULL,
497	    made_on    DATE           NOT NULL,
498	    state      CLOB           NOT NULL
499	);
500	CREATE INDEX history_entity ON history (sheet_id, kind, entity_id, id);
501	-- The date a statement was taken as of (its figures as they stood at the end of it); none when it
502	-- was taken as the sheet stood when it was taken.
503	ALTER TABLE person_statement ADD COLUMN as_of DATE;
504	-- Settings that carry a figure are dated: each value is recorded from a from-date and is in force
505	-- from it until the next from-date of the same key. Before every from-date a key takes the sheet's
506	-- starting value (floor 1.00, late percent 0.00, terms 14 days; none for the rest). A blank value
507	-- (no clerk limit, no cap, a grade without terms of its own) is NULL.
508	CREATE TABLE sheet_setting (
509	    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
510	    setting_key   VARCHAR(20)  NOT NULL,
511	    from_date     DATE         NOT NULL,
512	    setting_value VARCHAR(20),
513	    PRIMARY KEY (sheet_id, setting_key, from_date)
514	);
515	-- The values sheets held before this change stay in force for every date.
516	INSERT INTO sheet_setting SELECT id, 'floor', DATE '1900-01-01', CAST(due_floor AS VARCHAR) FROM sheet WHERE due_floor <> 1.00;
517	INSERT INTO sheet_setting SELECT id, 'terms', DATE '1900-01-01', CAST(terms AS VARCHAR) FROM sheet WHERE terms <> 14;
518	INSERT INTO sheet_setting SELECT id, 'late-pct', DATE '1900-01-01', CAST(late_pct AS VARCHAR) FROM sheet WHERE late_pct <> 0;
519	INSERT INTO sheet_setting SELECT id, 'clerk-limit', DATE '1900-01-01', CAST(clerk_limit AS VARCHAR) FROM sheet WHERE clerk_limit IS NOT NULL;
520	INSERT INTO sheet_setting SELECT id, 'cap', DATE '1900-01-01', CAST(due_cap AS VARCHAR) FROM sheet WHERE due_cap IS NOT NULL;
521	INSERT INTO sheet_setting SELECT sheet_id, 'terms-' || grade, DATE '1900-01-01', CAST(terms AS VARCHAR) FROM sheet_grade_terms;
522	DROP TABLE sheet_grade_terms;
523	ALTER TABLE sheet DROP COLUMN due_floor;
524	ALTER TABLE sheet DROP COLUMN terms;
525	ALTER TABLE sheet DROP COLUMN late_pct;
526	ALTER TABLE sheet DROP COLUMN clerk_limit;
527	ALTER TABLE sheet DROP COLUMN due_cap;
528	-- The sheet's pot: an amount with two decimals shared out among each balanced pool's members by
529	-- their shares; null when blank (none). Not dated.
530	ALTER TABLE sheet ADD COLUMN pot DECIMAL(15, 2);
531	-- A pool on the sheet: a name (at most once per sheet, compared ignoring case) and its members.
532	CREATE TABLE pool (
533	    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
534	    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
535	    name      VARCHAR(200) NOT NULL
536	);
537	CREATE INDEX pool_sheet ON pool (sheet_id, id);
538	
539	-- A member of a pool: a person of the sheet (at most once per pool) with a share percent
540	-- (more than 0.00, at most 100.00). A person may be in several pools.
541	CREATE TABLE pool_member (
542	    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
543	    pool_id    BIGINT NOT NULL REFERENCES pool (id),
544	    person_id  BIGINT NOT NULL REFERENCES person (id),
545	    share      DECIMAL(5, 2) NOT NULL CHECK (share > 0 AND share <= 100),
546	    UNIQUE (pool_id, person_id)
547	);
548	-- A pool membership may carry a from-date and a to-date (either optional, the to-date never before
549	-- the from-date): a member whose dates do not include the sheet's today is left out of the pool.
550	ALTER TABLE pool_member ADD COLUMN from_date DATE;
551	ALTER TABLE pool_member ADD COLUMN to_date DATE;
552	ALTER TABLE pool_member ADD CONSTRAINT pool_member_dates
553	    CHECK (from_date IS NULL OR to_date IS NULL OR to_date >= from_date);
554	-- A hold has a from-date and an optional to-date (null: open-ended), and a person may have several
555	-- over time. Only their OPEN claims dated within a hold (and not bound by a statement) are left out
556	-- of the live totals. A person held before keeps a hold from the beginning of time.
557	CREATE TABLE person_hold (
558	    person_id BIGINT NOT NULL REFERENCES person (id),
559	    position  INT    NOT NULL,
560	    from_date DATE   NOT NULL,
561	    to_date   DATE,
562	    CHECK (to_date IS NULL OR to_date >= from_date),
563	    PRIMARY KEY (person_id, position)
564	);
565	INSERT INTO person_hold (person_id, position, from_date, to_date)
566	    SELECT id, 0, DATE '0001-01-01', NULL FROM person WHERE held;
567	ALTER TABLE person DROP COLUMN held;
