# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
package net.officefloor.hq.app.pool;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A pool on the sheet: a name, unique on the sheet, and its members ({@link PoolMember}). */
@Entity
@Table(name = "pool")
public class Pool {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    protected Pool() {
    }

    public Pool(String sheetId, String name) {
        this.sheetId = sheetId;
        this.name = name;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }
}
package net.officefloor.hq.app.pool;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A person, or another pool, in a pool with their share percent (two decimals, more than 0.00,
 *  at most 100.00): exactly one of the person and the member pool is set. The membership may carry
 *  a from-date and a to-date (both inclusive, either optional). */
@Entity
@Table(name = "pool_member")
public class PoolMember {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "pool_id", nullable = false)
    private Long poolId;

    @Column(name = "person_id")
    private Long personId;

    @Column(name = "member_pool_id")
    private Long memberPoolId;

    @Column(name = "share", nullable = false, precision = 5, scale = 2)
    private BigDecimal share;

    @Column(name = "from_date")
    private LocalDate fromDate;

    @Column(name = "to_date")
    private LocalDate toDate;

    protected PoolMember() {
    }

    public PoolMember(Long poolId, Long personId, BigDecimal share) {
        this.poolId = poolId;
        this.personId = personId;
        this.share = share;
    }

    /** A pool as a member of another pool, with a share. */
    public static PoolMember ofPool(Long poolId, Long memberPoolId, BigDecimal share) {
        PoolMember member = new PoolMember(poolId, null, share);
        member.memberPoolId = memberPoolId;
        return member;
    }

    public Long getId() {
        return id;
    }

    public Long getPoolId() {
        return poolId;
    }

    public Long getPersonId() {
        return personId;
    }

    /** The pool that is this member, null for a person. */
    public Long getMemberPoolId() {
        return memberPoolId;
    }

    public BigDecimal getShare() {
        return share;
    }

    /** Move the membership to another person. */
    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public void setShare(BigDecimal share) {
        this.share = share;
    }

    /** The first day of the membership, null when it has no start. */
    public LocalDate getFromDate() {
        return fromDate;
    }

    /** The last day of the membership, null when it has no end. */
    public LocalDate getToDate() {
        return toDate;
    }

    public void setDates(LocalDate fromDate, LocalDate toDate) {
        this.fromDate = fromDate;
        this.toDate = toDate;
    }
}
package net.officefloor.hq.app.crew;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A crew on the sheet: a name, unique on the sheet, its lead (a person of the sheet; none once
 *  they have left it) and its members ({@link CrewMember}). */
@Entity
@Table(name = "crew")
public class Crew {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "lead_id")
    private Long leadId;

    protected Crew() {
    }

    public Crew(String sheetId, String name, Long leadId) {
        this.sheetId = sheetId;
        this.name = name;
        this.leadId = leadId;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    /** The lead's person id; null when the lead has left the sheet. */
    public Long getLeadId() {
        return leadId;
    }

    /** Move the lead to another person. */
    public void setLeadId(Long leadId) {
        this.leadId = leadId;
    }
}
package net.officefloor.hq.app.crew;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A person in a crew, other than its lead. */
@Entity
@Table(name = "crew_member")
public class CrewMember {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "crew_id", nullable = false)
    private Long crewId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    protected CrewMember() {
    }

    public CrewMember(Long crewId, Long personId) {
        this.crewId = crewId;
        this.personId = personId;
    }

    public Long getId() {
        return id;
    }

    public Long getCrewId() {
        return crewId;
    }

    public Long getPersonId() {
        return personId;
    }

    /** Move the membership to another person. */
    public void setPersonId(Long personId) {
        this.personId = personId;
    }
}
package net.officefloor.hq.app.crew;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.pool.PoolRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class CrewService {

    /** A crew with its members, in the order they were added. */
    public record CrewWithMembers(Crew crew, List<CrewMember> members) {
    }

    private final CrewRepository crews;
    private final CrewMemberRepository members;
    private final PersonRepository people;
    private final PoolRepository pools;
    private final SheetService sheets;
    private final Audit audit;

    public CrewService(CrewRepository crews, CrewMemberRepository members, PersonRepository people,
            PoolRepository pools, SheetService sheets, Audit audit) {
        this.crews = crews;
        this.members = members;
        this.people = people;
        this.pools = pools;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's crews in the order they were added, each with its members. */
    @Transactional(readOnly = true)
    public List<CrewWithMembers> list(String sheetId) {
        List<Crew> all = crews.findBySheetIdOrderByIdAsc(sheetId);
        Map<Long, List<CrewMember>> byCrew = members.findByCrewIdInOrderByIdAsc(all.stream().map(Crew::getId).toList())
                .stream().collect(Collectors.groupingBy(CrewMember::getCrewId));
        return all.stream().map(c -> new CrewWithMembers(c, byCrew.getOrDefault(c.getId(), List.of()))).toList();
    }

    /** Add a crew led by a person of the sheet; refused (404) for a person not on the sheet, (409)
     *  when the sheet has a crew or a pool (a crew is a pool too) of the name already. */
    @Transactional
    public Crew add(String sheetId, String user, String name, long leadId) {
        sheets.load(sheetId, user);
        sheets.lock(sheetId);
        Person lead = people.findByIdAndSheetId(leadId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (crews.findBySheetIdAndNameIgnoreCase(sheetId, name).isPresent()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet has a crew of that name");
        }
        if (pools.findBySheetIdAndNameIgnoreCase(sheetId, name).isPresent()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet has a pool of that name");
        }
        Crew crew = crews.saveAndFlush(new Crew(sheetId, name, lead.getId()));
        audit.recordOnCommit("CREW_ADDED sheet=" + sheetId + " by=" + user + " name=" + name
                + " lead=" + lead.getName());
        return crew;
    }

    /** Add a person of the sheet to a crew; refused (404) for a crew or person not on the sheet,
     *  (409) when the person is the crew's lead or in the crew already. */
    @Transactional
    public CrewMember addMember(String sheetId, String user, String crewName, long personId) {
        sheets.lock(sheetId);
        Crew crew = crews.findBySheetIdAndNameIgnoreCase(sheetId, crewName)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such crew"));
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (person.getId().equals(crew.getLeadId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person leads the crew");
        }
        if (members.existsByCrewIdAndPersonId(crew.getId(), person.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person is in the crew already");
        }
        CrewMember member = members.saveAndFlush(new CrewMember(crew.getId(), person.getId()));
        audit.recordOnCommit("CREW_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " crew=" + crew.getName()
                + " name=" + person.getName());
        return member;
    }

    /** Carry a merged person's crews to the person they are merged into: the crews they lead are
     *  led by the other (who leaves the crew's members if among them), and their memberships move to
     *  the other unless the other leads the crew or is in it already. */
    @Transactional
    public void merge(Long fromId, Long intoId) {
        for (Crew crew : crews.findByLeadIdOrderByIdAsc(fromId)) {
            crew.setLeadId(intoId);
            members.findByCrewIdInOrderByIdAsc(List.of(crew.getId())).stream()
                    .filter(m -> m.getPersonId().equals(intoId)).forEach(members::delete);
        }
        crews.flush();
        for (CrewMember member : members.findByPersonIdOrderByIdAsc(fromId)) {
            Crew crew = crews.findById(member.getCrewId()).orElseThrow();
            if (intoId.equals(crew.getLeadId()) || members.existsByCrewIdAndPersonId(crew.getId(), intoId)) {
                members.delete(member);
            } else {
                member.setPersonId(intoId);
            }
        }
        members.flush();
    }

    /** Drop a person leaving the sheet from its crews: their memberships, and the lead of the crews
     *  they lead, those crews staying with their members and no lead. */
    @Transactional
    public void drop(Long personId) {
        members.deleteAll(members.findByPersonIdOrderByIdAsc(personId));
        members.flush();
        for (Crew crew : crews.findByLeadIdOrderByIdAsc(personId)) {
            crew.setLeadId(null);
        }
        crews.flush();
    }
}
